export default {
  namespaced: true,
  state: {
    taskId: 0,
    levelId: 0,
    categoryId: 0 // 文章分类id
  },
  mutations: {
    /**
     * @description 设置设备类型
     * @param {Object} state vuex state
     * @param {String} type 设备类型，可选值为 Mobile、Tablet、Desktop
     */
    /**
     * @description 会员任务id
     */
    getTaskId: function getTaskId(state, taskId) {
      state.taskId = taskId;
    },
    /**
     * @description 会员等级id
     */
    getlevelId: function getlevelId(state, levelId) {
      state.levelId = levelId;
    },
    /**
     * @description 文章分类id
     */
    getCategoryId: function getCategoryId(state, categoryId) {
      state.categoryId = categoryId;
    }
  },
  actions: {
    /**
     * @description 初始化监听全屏状态
     */
    listenFullscreen: function listenFullscreen(_ref) {
      var commit = _ref.commit;
      return new Promise(function (resolve) {
        if (screenfull.enabled) {
          screenfull.on('change', function () {
            if (!screenfull.isFullscreen) {
              commit('setFullscreen', false);
            }
          });
        }
        // end
        resolve();
      });
    },
    /**
     * @description 切换全屏
     */
    toggleFullscreen: function toggleFullscreen(_ref2) {
      var commit = _ref2.commit;
      return new Promise(function (resolve) {
        if (screenfull.isFullscreen) {
          screenfull.exit();
          commit('setFullscreen', false);
        } else {
          screenfull.request();
          commit('setFullscreen', true);
        }
        // end
        resolve();
      });
    }
  }
};
